const items=$input.all();
if(items.length!==1)throw new Error('Se requiere un evento de Slack por ejecución.');
const e=items[0].json;
if(e.source==='gmail'){
 const email=String(e.From||'').trim().toLowerCase();
 if(!/^[^\s<>@,;]+@[^\s<>@,;]+\.[^\s<>@,;]+$/.test(email)||!e.message_id||!e.BodyText||!e.mailbox||!/^C[A-Z0-9]+$/.test(e.ops_channel||''))throw new Error('Contrato Gmail incompleto.');
 const ms=Date.parse(e.received_at);if(!Number.isFinite(ms))throw new Error('Fecha Gmail inválida.');
 return [{json:{source:'gmail',request_id:'gmail:'+e.mailbox+':'+e.message_id,text:(String(e.Subject)+'\n'+String(e.BodyText)).slice(0,6000),language:'es',simulate_failure:false,channel:e.ops_channel,thread_ts:'',user_id:email,session_id:'gmail:'+e.mailbox.toLowerCase()+':'+email,event_ts:(ms/1000).toFixed(6),email,message_id:e.message_id,subject:e.Subject}}];
}

if(e.bot_id||e.bot_profile||e.subtype||typeof e.text!=='string'||!e.text.trim())return [];
if(typeof e.user!=='string'||!e.user||typeof e.channel!=='string'||!e.channel||!/^\d+\.\d{6}$/.test(e.ts||''))throw new Error('Evento Slack sin identidad o timestamp válido.');
return [{json:{
 source:'slack',request_id:e.channel+':'+e.ts,
 text:e.text.slice(0,6000),language:'es',simulate_failure:false,
 channel:e.channel,thread_ts:e.thread_ts||e.ts,user_id:e.user,
 session_id:['slack',e.team||e.team_id||'workspace_actual',e.channel,e.user].join(':'),
 event_ts:e.ts
}}];

const ctx=$('Contexto Manager').first().json;
const rows=$input.all().map(i=>i.json);
if(rows.some(r=>r.error))throw new Error('Lectura de memoria fallida.');
if(rows.some(r=>Object.keys(r).length>0&&r.Session_ID!==ctx.session_id))throw new Error('La búsqueda devolvió una sesión incorrecta.');
const matches=rows.filter(r=>r.Session_ID===ctx.session_id);
if(matches.length>1)throw new Error('Session_ID duplicada.');
const exists=matches.length===1;
const clean=v=>String(v).replace(/<[^>]*>/g,'').replace(/\[(?:INICIO|FIN) DE CONTEXTO COMPARTIDO\]/g,'').replace(/@(channel|here|everyone)\b/gi,'$1');
const profile=ctx.source==='gmail'?{ok:true,user:{name:ctx.email}}:$('Nombre del usuario Slack').first().json;
let summary,meta,case_status;
if(exists){
 const row=matches[0];
 summary=JSON.parse(row['Resumen consolidado']);
 meta=JSON.parse(row['Datos clave']);
 case_status=row['Estado del caso'];
}else{
 summary={asunto_principal:'Sin historial previo',puntos_clave:[],accion_requerida:'Analizar la primera consulta'};
 const name=(profile.ok&&(profile.user?.profile?.display_name||profile.user?.profile?.real_name||profile.user?.name))||('Usuario '+ctx.user_id);
 meta={schema_version:'1.0',user_id:ctx.user_id,user_name:clean(name).slice(0,100),total_messages:0,messages_since_summary:0,pending_points:[],last_request_id:'',last_event_ts:'',summary_runs:0};
 case_status='NUEVO';
}
const validSummary=summary&&typeof summary.asunto_principal==='string'&&summary.asunto_principal.length<=240&&Array.isArray(summary.puntos_clave)&&summary.puntos_clave.length<=10&&summary.puntos_clave.every(p=>typeof p==='string'&&p.length<=240)&&typeof summary.accion_requerida==='string'&&summary.accion_requerida.length<=300;
const validMeta=meta&&meta.schema_version==='1.0'&&meta.user_id===ctx.user_id&&typeof meta.user_name==='string'&&meta.user_name.length>0&&meta.user_name.length<=100&&Number.isInteger(meta.total_messages)&&meta.total_messages>=0&&Number.isInteger(meta.messages_since_summary)&&meta.messages_since_summary>=0&&meta.messages_since_summary<=5&&meta.total_messages>=meta.messages_since_summary&&Array.isArray(meta.pending_points)&&meta.pending_points.length===meta.messages_since_summary&&meta.pending_points.every(p=>typeof p==='string'&&p.length<=240)&&typeof meta.last_request_id==='string'&&typeof meta.last_event_ts==='string'&&(!meta.last_event_ts||/^\d+\.\d{6}$/.test(meta.last_event_ts))&&Number.isInteger(meta.summary_runs)&&meta.summary_runs>=0;
if(!validSummary||!validMeta||!['NUEVO','EN_SEGUIMIENTO','REQUIERE_REVISION'].includes(case_status))throw new Error('Memoria inválida o identidad discordante.');
if(meta.last_request_id===ctx.request_id||(ctx.source!=='gmail'&&meta.last_event_ts&&Number(ctx.event_ts)<=Number(meta.last_event_ts)))return [];
return [{json:{exists,session_id:ctx.session_id,user_name:clean(meta.user_name),last_summary:clean(JSON.stringify(summary)),case_status,summary,meta}}];

const value=$input.first().json.output;
const parsed=typeof value==='string'?JSON.parse(value):value;
if(!parsed||typeof parsed!=='object')throw new Error('El agente no devolvió una clasificación.');
const route=['TECH_SUPPORT','BILLING','HUMAN'].includes(parsed.route)&&typeof parsed.confidence==='number'&&parsed.confidence>=0.8&&parsed.confidence<=1?parsed.route:'HUMAN';
const priority=['critica','alta','normal','baja'].includes(parsed.priority)?parsed.priority:'normal';
return [{json:{classification:{route,priority,confidence:route==='HUMAN'?0:parsed.confidence}}}];

const input=$input.first().json;
const ctx=$('Contexto Manager').first().json;
const mem=$('Memoria disponible').first().json;
const clean=v=>String(v).replace(/<[^>]*>/g,'').replace(/\[(?:INICIO|FIN) DE CONTEXTO COMPARTIDO\]/g,'').replace(/@(channel|here|everyone)\b/gi,'$1');
const priorities=['critica','alta','normal','baja'];
const valid=input.schema_version==='1.0'&&input.request_id===ctx.request_id&&['TECH_SUPPORT','BILLING'].includes(input.worker)&&['success','error'].includes(input.status)&&typeof input.data?.summary==='string'&&typeof input.data?.reply==='string'&&priorities.includes(input.data.priority)&&typeof input.data.escalate==='boolean'&&['soporte_tecnico','facturacion','soporte_general','seguridad'].includes(input.data.team)&&(input.status==='success'?input.error===null:typeof input.error?.code==='string');
const human=input.classification?.route==='HUMAN'&&!input.error;
const worker=valid?input.worker:'HUMAN';
const status=valid?input.status:(human?'needs_review':'error');
const summary=clean(valid?input.data.summary:'Se requiere revisión humana por intención, clasificación o fallo del procesamiento.').slice(0,240);
const priority=valid?input.data.priority:(priorities.includes(input.classification?.priority)?input.classification.priority:'normal');
const escalate=valid?(input.data.escalate||input.status!=='success'||['critica','alta'].includes(priority)):true;
const team=valid?input.data.team:'soporte_general';
const reply=clean(valid?input.data.reply:'Tu consulta requiere revisión de una persona del equipo de soporte.').slice(0,2000);
const error_code=valid?(input.error?.code||''):(human?'':'MANAGER_FALLBACK');
return [{json:{
 request_id:ctx.request_id,worker,status,summary,priority,escalate,team,reply,error_code,channel:ctx.channel,thread_ts:ctx.thread_ts,
 session_id:mem.session_id,user_name:mem.user_name,new_count:mem.meta.messages_since_summary+1,total_messages:mem.meta.total_messages+1,
 pending_points:[...mem.meta.pending_points,summary],previous_summary:mem.summary,
 case_status:escalate?'REQUIERE_REVISION':'EN_SEGUIMIENTO',
 current_action:escalate?'Revisión humana por el equipo '+team:'Esperar aclaración del usuario o seguimiento del caso',
 current_text:ctx.text,event_ts:ctx.event_ts
}}];

const turn=$('Integrar resultado').first().json;
const mem=$('Memoria disponible').first().json;
const ctx=$('Contexto Manager').first().json;
let summary,pending_points,messages_since_summary,summary_runs;
if(turn.new_count>5){
 const raw=$input.first().json;
 const value=raw.output ?? raw.text ?? raw;
 summary=typeof value==='string'?JSON.parse(value):value;
 const valid=summary&&Object.keys(summary).sort().join(',')==='accion_requerida,asunto_principal,puntos_clave'&&typeof summary.asunto_principal==='string'&&summary.asunto_principal.length<=240&&Array.isArray(summary.puntos_clave)&&summary.puntos_clave.length<=10&&summary.puntos_clave.every(p=>typeof p==='string'&&p.length<=240)&&typeof summary.accion_requerida==='string'&&summary.accion_requerida.length<=300&&!/<[^>]+>/.test(JSON.stringify(summary))&&!/\[(?:INICIO|FIN) DE CONTEXTO COMPARTIDO\]/.test(JSON.stringify(summary));
 if(!valid)throw new Error('Resumen de Groq inválido: no sobrescribir la memoria.');
 pending_points=[];messages_since_summary=0;summary_runs=mem.meta.summary_runs+1;
}else{
 summary={asunto_principal:turn.summary,puntos_clave:[...new Set([...turn.previous_summary.puntos_clave,...turn.pending_points])].slice(-10),accion_requerida:turn.current_action};
 pending_points=turn.pending_points;messages_since_summary=turn.new_count;summary_runs=mem.meta.summary_runs;
}
return [{json:{
 Session_ID:mem.session_id,
 'Fecha de actualización':$now.toISO(),
 'Resumen consolidado':JSON.stringify(summary),
 'Estado del caso':turn.case_status,
 'Datos clave':JSON.stringify({schema_version:'1.0',user_id:ctx.user_id,user_name:mem.user_name,total_messages:turn.total_messages,messages_since_summary,pending_points,last_request_id:ctx.request_id,last_event_ts:ctx.event_ts,summary_runs})
}}];
